class RuntimeIssue implements Exception {
  final Position position;
  final String message;
  RuntimeIssue(this.position, this.message);
}

Never runtimeError(Position position, String message) =>
    throw RuntimeIssue(position, message);
String formatOutput(List<Value> values, Position position) {
  final format = values[0].text;
  var argument = 1, i = 0;
  final out = StringBuffer();
  while (i < format.length) {
    if (format[i] != '%') {
      out.write(format[i++]);
      continue;
    }
    i++;
    if (i < format.length && format[i] == '%') {
      out.write('%');
      i++;
      continue;
    }
    var left = false, zero = false;
    while (i < format.length && (format[i] == '-' || format[i] == '0')) {
      left = left || format[i] == '-';
      zero = zero || format[i] == '0';
      i++;
    }
    var start = i;
    while (i < format.length && digit(format.codeUnitAt(i))) i++;
    final width = i > start ? decimal(format.substring(start, i)) : 0;
    var precision = -1;
    if (i < format.length && format[i] == '.') {
      start = ++i;
      while (i < format.length && digit(format.codeUnitAt(i))) i++;
      precision = i > start ? decimal(format.substring(start, i)) : 0;
    }
    if (i == format.length || !'discxo'.contains(format[i]))
      runtimeError(position, 'invalid format');
    final kind = format[i++];
    if (argument == values.length)
      runtimeError(position, 'not enough arguments');
    final value = values[argument++];
    var body = '';
    if ('dixo'.contains(kind)) {
      final n = value.number;
      final base = kind == 'x'
          ? 16
          : kind == 'o'
          ? 8
          : 10;
      var digits = n.abs().toRadixString(base);
      if (precision == 0 && n == 0) digits = '';
      if (precision > digits.length) digits = digits.padLeft(precision, '0');
      body = n < 0 ? '-$digits' : digits;
      if (body.length < width) {
        final pad = width - body.length;
        if (left) {
          body = body.padRight(width);
        } else if (zero && precision < 0) {
          body = n < 0
              ? '-${digits.padLeft(digits.length + pad, '0')}'
              : body.padLeft(width, '0');
        } else {
          body = body.padLeft(width);
        }
      }
    } else {
      if (kind == 's') {
        body = value.text;
        if (precision >= 0 && body.length > precision)
          body = body.substring(0, precision);
      } else if (value.kind == 'number' || value.kind == 'strnum') {
        final n = value.number;
        if (n != 10 && (n < 32 || n > 126))
          runtimeError(position, 'invalid character code');
        body = String.fromCharCode(n);
      } else {
        body = value.text;
        if (body.length > 1) body = body.substring(0, 1);
      }
      if (body.length < width)
        body = left ? body.padRight(width) : body.padLeft(width);
    }
    out.write(body);
  }
  return out.toString();
}

Value invokeBuiltin(String name, List<Value> values, Position position) {
  switch (name) {
    case 'substr':
      final text = values[0].text;
      var start = values[1].number;
      var end = values.length == 3 ? start + values[2].number : text.length + 1;
      start = max(start, 1);
      end = min(end, text.length + 1);
      return stringValue(end > start ? text.substring(start - 1, end - 1) : '');
    case 'index':
      final haystack = values[0].text, part = values[1].text;
      return numeric(part.isEmpty ? 0 : haystack.indexOf(part) + 1);
    case 'toupper':
      return stringValue(values[0].text.toUpperCase());
    case 'tolower':
      return stringValue(values[0].text.toLowerCase());
    case 'int':
      return numeric(values[0].number);
    case 'sprintf':
      return stringValue(formatOutput(values, position));
  }
  throw StateError('unknown built-in');
}

part of 'main.dart';

class Position {
  final int line, column;
  const Position(this.line, this.column);
  String toString() => '$line:$column';
}

class SyntaxIssue implements Exception {
  final Position position;
  SyntaxIssue(this.position);
}

class Token {
  final String kind, spelling, text;
  final int number;
  final Position position;
  Token(
    this.kind,
    this.spelling,
    this.position, {
    this.text = '',
    this.number = 0,
  });
}

bool letter(int c) => c >= 65 && c <= 90 || c >= 97 && c <= 122;
bool digit(int c) => c >= 48 && c <= 57;
bool wordIn(String words, String value) => words.split(' ').contains(value);
int decimal(String text) => int.parse(text);
List<Token> tokenize(String source) {
  final tokens = <Token>[];
  var i = 0, line = 1, column = 1;
  while (i < source.length) {
    var c = source.codeUnitAt(i);
    final position = Position(line, column);
    if (c == 32) {
      i++;
      column++;
      continue;
    }
    if (c == 92 && i + 1 < source.length && source.codeUnitAt(i + 1) == 10) {
      i += 2;
      line++;
      column = 1;
      continue;
    }
    if (c == 35) {
      while (i < source.length && source.codeUnitAt(i) != 10) {
        i++;
        column++;
      }
      continue;
    }
    if (c == 10) {
      tokens.add(Token('newline', '\n', position));
      i++;
      line++;
      column = 1;
      continue;
    }
    if (digit(c)) {
      final start = i;
      while (i < source.length && digit(source.codeUnitAt(i))) {
        i++;
        column++;
      }
      final text = source.substring(start, i);
      tokens.add(Token('number', text, position, number: decimal(text)));
      continue;
    }
    if (letter(c) || c == 95) {
      final start = i;
      while (i < source.length &&
          (letter(source.codeUnitAt(i)) ||
              digit(source.codeUnitAt(i)) ||
              source.codeUnitAt(i) == 95)) {
        i++;
        column++;
      }
      final text = source.substring(start, i);
      var kind = 'name';
      if (wordIn(
        'BEGIN END function if else while for do break continue next exit return delete in getline print printf',
        text,
      )) {
        kind = 'keyword';
      } else if (wordIn(
        'length substr index split sprintf toupper tolower close int',
        text,
      )) {
        kind = 'builtin';
      } else if (i < source.length && source[i] == '(') {
        kind = 'function_name';
      }
      tokens.add(Token(kind, text, position));
      continue;
    }
    if (c == 34) {
      final start = i;
      i++;
      column++;
      final value = StringBuffer();
      while (true) {
        if (i == source.length || source.codeUnitAt(i) == 10)
          throw SyntaxIssue(position);
        c = source.codeUnitAt(i++);
        column++;
        if (c == 34) break;
        if (c == 92) {
          final slash = Position(line, column - 1);
          if (i == source.length) throw SyntaxIssue(slash);
          c = source.codeUnitAt(i++);
          column++;
          c = switch (c) {
            110 => 10,
            116 => 9,
            92 || 34 || 47 => c,
            _ => throw SyntaxIssue(slash),
          };
        }
        value.writeCharCode(c);
      }
      tokens.add(
        Token(
          'string',
          source.substring(start, i),
          position,
          text: value.toString(),
        ),
      );
      continue;
    }
    var symbol = '';
    if (i + 1 < source.length &&
        wordIn(
          '+= -= *= /= %= ^= == <= >= != ++ -- && || >>',
          source.substring(i, i + 2),
        )) {
      symbol = source.substring(i, i + 2);
    } else if ('+-*/%^!><?:=()[]{},;\$'.contains(source[i])) {
      symbol = source[i];
    }
    if (symbol.isEmpty) throw SyntaxIssue(position);
    tokens.add(Token('symbol', symbol, position));
    i += symbol.length;
    column += symbol.length;
  }
  tokens.add(
    Token(
      'end',
      '',
      Position(source.codeUnits.where((c) => c == 10).length + 1, 1),
    ),
  );
  return tokens;
}

